    22	function shortWav() {
    23	  const buffer = Buffer.alloc(44 + 1600);
    24	  buffer.write('RIFF'); buffer.writeUInt32LE(buffer.length - 8, 4);
    25	  buffer.write('WAVEfmt ', 8); buffer.writeUInt32LE(16, 16);
    26	  buffer.writeUInt16LE(1, 20); buffer.writeUInt16LE(1, 22);
    27	  buffer.writeUInt32LE(16000, 24); buffer.writeUInt32LE(32000, 28);
    28	  buffer.writeUInt16LE(2, 32); buffer.writeUInt16LE(16, 34);
    29	  buffer.write('data', 36); buffer.writeUInt32LE(1600, 40);
    30	  for (let i = 0; i < 800; i++) buffer.writeInt16LE(Math.round(Math.sin(i / 10) * 500), 44 + i * 2);
    31	  return buffer;
    32	}
